function renderFamilyStep(){return `<div class="eyebrow">Место для каждого</div><h1>Кто будет<br>за столом?</h1><p class="intro">Своя порция и свои особенности<br>для каждого человека.</p><div class="people-count"><span>Человек в семье</span><div class="counter"><button id="minus" aria-label="Убрать человека" ${draft.people.length===1?'disabled':''}>−</button><strong>${draft.people.length}</strong><button id="plus" aria-label="Добавить человека" ${draft.people.length===8?'disabled':''}>+</button></div></div>${draft.people.map((n,i)=>`<div class="family-person"><div class="family-heading"><span class="avatar">${i+1}</span><div><h2>Человек ${i+1}</h2><small>Порции и предпочтения</small></div></div><div class="calorie-setting"><label for="person-${i}">Калорийность<small>На один день</small></label><div class="calorie-control"><input id="person-${i}" type="number" min="500" max="6000" value="${n}" aria-label="Калории человека ${i+1}"><span>ккал</span></div></div><label class="pregnancy-check"><span>Меню для беременных</span><input type="checkbox" id="pregnant-${i}" ${draft.pregnant[i]?'checked':''} aria-label="Меню для беременных, человек ${i+1}"></label>${dietaryFields(i)}</div>`).join('')}<p class="note">Общие блюда исключают продукты, отмеченные у любого члена семьи. Аллергии проверяем по рецептам: перед покупкой проверьте состав упаковки и предупреждения о следах аллергенов.</p><p class="note">При отметке беременности ограничения по продуктам применятся к общим блюдам. Норму калорий не меняем: укажите свою, согласованную с врачом. Это базовый фильтр, не индивидуальная медицинская диета.</p>`}
function prepStep(){return `<div class="eyebrow">Освободим время</div><h1>Как часто<br>будем готовить?</h1><p class="intro">Можно приготовить всё заранее<br>и возвращаться на кухню реже.</p><div class="prep-options" role="radiogroup" aria-label="Частота готовки">${[[1,'Каждый день','Новые блюда каждый день','7'],[3,'На 3 дня за раз','Готовка: пн, чт и вс','3'],[4,'На 4 дня за раз','Готовка: пн и пт','2']].map(([n,title,desc,count])=>`<button class="prep-option ${draft.prepDays===n?'selected':''}" role="radio" aria-checked="${draft.prepDays===n}" data-prep="${n}"><span class="prep-number">${count}</span><span><b>${title}</b><small>${desc}</small></span><span class="tick">✓</span></button>`).join('')}</div><div class="pref-explanation"><b>${draft.prepDays===1?'Больше разных блюд':'Меньше готовки — несколько блюд в партии'}</b><p>${draft.prepDays===1?'Подберём 21 приём пищи с минимумом повторов.':'В одну готовку подготовим до двух завтраков и двух основных блюд. Они будут чередоваться. Покажем точные количества продуктов на всю партию и порции на каждый день.'}</p></div><p class="note">Для режима на 3–4 дня нужна морозилка: порции на поздние дни замораживаем сразу. Между готовками — только разморозка, разогрев и подача. «Быстрое» означает до 30 минут на обычный объём одного рецепта; вся партия займёт больше времени.</p>`}
function prepSummary(){return `<div class="prep-summary"><div><b>${plan.prepDays===1?'Готовим каждый день':`${plan.sessions.length} готовки на неделю`}</b><p>${plan.prepDays===1?'Можно переключиться на заготовки на 3–4 дня.':plan.sessions.map(s=>short[s.start].toLowerCase()).join(' + ')+' · между готовками разогреваем порции'}</p></div><button id="show-prep" class="text-button">${plan.prepDays===1?'Настроить':'План готовки →'}</button></div>${pregnancyActive(plan)?'<div class="goal-badges"><span>Учитываем беременность · калории не меняем</span></div>':''}`}
function prepDayLabel(d){if(plan.prepDays===1)return '';const session=plan.sessions.find(s=>d>=s.start&&d<=s.end);return d===session.start?`<span class="cooking-label">Готовим на ${session.end-session.start+1} дн.</span>`:`<span class="cooking-label reheat">Только разогрев · готовили ${short[session.start].toLowerCase()}</span>`}
function renderPrep(){
 $('#screen').innerHTML=`<section class="enter"><div class="eyebrow">Готовим реже</div><h1>План готовки</h1><p class="intro">${prepLabel(plan.prepDays)}.<br>${plan.prepDays===1?'Выберите готовку на 3–4 дня в настройках, чтобы собирать партии.':'В дни между готовками — разморозить, разогреть и подать.'}</p><button class="text-button" id="change-prep">Изменить частоту готовки</button>${plan.sessions.map(s=>`<section class="prep-session"><div class="session-title"><span>${short[s.start]}</span><div><h2>${days[s.start]}</h2><small>Меню: ${short[s.start]}${s.end!==s.start?' — '+short[s.end]:''} · ${s.batches.length} блюда</small></div></div>${s.batches.map(b=>`<button class="batch-card" data-batch="${b.key}"><span class="meal-icon">${recipes[b.id].emoji}</span><span><b>${recipes[b.id].name}</b><small>${b.portions} порций · ${appliances.find(a=>a[0]===b.method)[1]}<br>${[...new Set(b.servings.map(o=>short[o.d]))].join(', ')}</small></span><span>↗</span></button>`).join('')}<p class="note">Готовьте партиями по вместимости прибора. Время зависит от объёма и возможности готовить параллельно.</p></section>`).join('')}${plan.prepDays>1?storageHelp({ing:{}},plan):''}${pregnancyHelp(plan)}</section>`;
 $('#change-prep').onclick=()=>startWizard(5);document.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>openBatch(b.dataset.batch));
}
function preparationSteps(m){const list=[...instructions(m)];if(plan.prepDays>1&&m.id===0)list.push('Для заготовки вмешайте яблоко в горячую кашу и прогрейте перед разделением на контейнеры.');if(pregnancyActive(plan)){const ing=recipes[m.id].ing;if(ing.chicken||ing.turkey||ing.beef||ing.fish||ing.egg)list.push('При беременности доведите мясо, рыбу и яйца до полной готовности. Для проверки мяса используйте пищевой термометр; птица — 74 °C в центре.');if(Object.keys(ing).some(k=>['milk','curd','yogurt','cheese','sour'].includes(k)))list.push('Используйте молочные продукты из пастеризованного молока и соблюдайте срок годности на упаковке.')}return list}
function openBatch(key){const session=plan.sessions.find(s=>s.batches.some(b=>b.key===key)),b=session?.batches.find(b=>b.key===key);if(!b)return;const r=recipes[b.id];$('#recipe-content').innerHTML=`<div class="eyebrow">Готовим ${days[session.start]} · вся партия</div><h2>${r.name}</h2><p>${b.portions} порций · ${appliances.find(a=>a[0]===b.method)[1]}</p><div class="portion-info">Это продукты на все указанные дни и всю семью. Не умножайте ещё раз на число людей.</div><h3>На всю партию</h3><ul>${Object.entries(b.ingredients).map(([k,g])=>`<li>${productLabel(k,plan)}<span>${Math.round(g)} г</span></li>`).join('')}</ul>${recipeSource(recipes[b.id])}<h3>Как приготовить</h3><ol>${preparationSteps(b).map(t=>`<li>${t}</li>`).join('')}</ol><h3>Разложить по контейнерам</h3><p>Процент ниже — доля от готовой партии. Взвесьте её после приготовления и отделите указанную долю каждому человеку.</p><div class="serving-list">${b.servings.map(o=>`<div class="serving-item"><b>${days[o.d]} · ${mealNames[o.m]}</b><span class="storage-chip ${o.storage}">${storageLabel(o.storage)}</span><small>${plan.people.map((n,i)=>`Человек ${i+1}: ${(n*shares[o.m]/kcal(r)/b.factor*100).toFixed(1)}% партии · ${Math.round(n*shares[o.m])} ккал`).join('<br>')}</small></div>`).join('')}</div>${plan.prepDays>1?storageHelp(r,plan):''}${pregnancyHelp(plan)}`;$('#recipe').showModal()}
function renderRecipeDetails(d,i){const m=plan.meals[d][i],r=recipes[m.id];$('#recipe-content').innerHTML=`<div class="eyebrow">${days[d]} · ${mealNames[i]}</div><h2>${r.name}</h2><p>${appliances.find(a=>a[0]===m.method)[1]} · ≈ ${m.time} мин на обычный объём · ${rub(m.cost)}</p>${plan.prepDays>1?`<div class="portion-info">Готовим ${days[m.prepDay].toLowerCase()}. ${storageLabel(m.storage)}.<button class="text-button" id="full-batch">Ингредиенты на всю партию →</button></div>`:''}${m.id===1?'<img class="recipe-photo" src="food.jpg" alt="Иллюстрация подачи блюда"><p class="photo-credit">Иллюстрация подачи, состав на фото может отличаться · Povar.ru</p>':''}<h3>На этот приём пищи всей семье</h3><ul>${Object.entries(r.ing).map(([k,g])=>`<li>${productLabel(k,plan)}<span>${Math.round(g*m.factor)} г</span></li>`).join('')}</ul>${recipeSource(r)}<h3>Как приготовить</h3><ol>${preparationSteps(m).map(t=>`<li>${t}</li>`).join('')}</ol><h3>Каждому — своя порция</h3><div class="portion-pills">${plan.people.map((p,j)=>`<span>Человек ${j+1}${plan.pregnant[j]?' · беременность':''}<br><b>${(p/plan.totalKcal*100).toFixed(1)}% блюда · ${Math.round(p*shares[i])} ккал</b></span>`).join('')}</div><p class="note">Взвесьте готовое блюдо и разделите по долям. Вес продуктов — до приготовления, яиц — без скорлупы. Калории ориентировочные.</p>${plan.prepDays>1?storageHelp(r,plan):''}${pregnancyHelp(plan)}`;if($('#full-batch'))$('#full-batch').onclick=()=>openBatch(m.batchKey);$('#recipe').showModal()}

function recipeSource(r){return r.ideaUrl?'<p class="note">Адаптация для нашего меню. <a href="'+r.ideaUrl+'" target="_blank" rel="noreferrer">Идея блюда на Food.ru ↗</a>. Состав, порции и калории рассчитаны здесь.</p>':'<p class="note">Рецепт составлен для прототипа на основе типового блюда; не импортирован с Food.ru. Калорийность ориентировочная.</p>'}
